<script setup>
import {computed,ref,watch} from 'vue'
import {useData} from 'vitepress'
import BrandLockup from './BrandLockup.vue'
import {homePath,sitePath} from '../../site-routes.mjs'
const props=defineProps({locale:String,active:String,isDoc:Boolean,switchRoute:String})
const emit=defineEmits(['search','directory'])
const {isDark}=useData(),menu=ref(false),toggle=ref(null),en=computed(()=>props.locale==='en')
watch(()=>props.active,()=>{menu.value=false})
function dismiss(event){if(event.key==='Escape'&&menu.value){menu.value=false;toggle.value?.focus()}}
</script>
<template><header class="site-header" @keydown="dismiss"><a class="brand" :href="homePath(locale)" :aria-label="en?'RivoMesh home':'RivoMesh 首页'"><BrandLockup/></a><span class="header-divider"></span><span class="header-product">{{en?'Database replication':'数据库实时同步平台'}}</span><nav id="main-navigation" class="main-nav" :class="{open:menu}" @click="event=>{if(event.target.closest('a'))menu=false}" :aria-label="en?'Main navigation':'主导航'"><a :href="homePath(locale)" :class="{current:active===homePath(locale)}" :aria-current="active===homePath(locale)?'page':undefined">{{en?'Home':'首页'}}</a><a :href="`/docs/${locale}/start/index.html`" :class="{current:isDoc}">{{en?'Docs':'文档'}}</a><a :href="`/docs/${locale}/start/connectors.html`">{{en?'Connectors':'连接器'}}</a><a :href="`/docs/${locale}/start/xinchuang.html`">{{en?'Database adaptation':'信创适配'}}</a><a :href="sitePath(locale,'download')">{{en?'Download':'下载'}}</a><a :href="sitePath(locale,'community')">{{en?'Community':'社区'}}</a></nav><div class="header-actions"><button class="search-trigger" @click="emit('search')" :aria-label="en?'Search documentation':'搜索文档'"><span aria-hidden="true">⌕</span><span class="search-label">{{en?'Search':'搜索'}}</span><kbd>⌘ K</kbd></button><a class="language-switch" :href="switchRoute" :lang="en?'zh-CN':'en'" :aria-label="en?'切换到中文':'Read this page in English'">{{en?'中文':'EN'}}</a><button class="theme-toggle" @click="isDark=!isDark" :aria-label="isDark?(en?'Switch to light theme':'切换浅色主题'):(en?'Switch to dark theme':'切换深色主题')">{{isDark?'☀':'☾'}}</button><a class="github-icon" href="https://github.com/rivomesh/rivomesh" target="_blank" rel="noreferrer" :aria-label="en?'Source on GitHub':'GitHub 源码'"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 .9a11.1 11.1 0 0 0-3.5 21.6c.6.1.8-.2.8-.5v-2.1c-3.4.7-4.1-1.5-4.1-1.5-.5-1.4-1.3-1.8-1.3-1.8-1.1-.8.1-.7.1-.7 1.2.1 1.8 1.2 1.8 1.2 1.1 1.8 2.8 1.3 3.5 1 .1-.8.4-1.3.8-1.6-2.7-.3-5.5-1.4-5.5-6.1 0-1.4.5-2.5 1.2-3.3-.1-.3-.5-1.6.1-3.3 0 0 1-.3 3.4 1.2a11.4 11.4 0 0 1 6.2 0c2.4-1.5 3.4-1.2 3.4-1.2.7 1.7.3 3 .2 3.3.8.8 1.2 1.9 1.2 3.3 0 4.7-2.9 5.8-5.6 6.1.4.4.8 1.1.8 2.2V22c0 .3.2.6.8.5A11.1 11.1 0 0 0 12 .9Z"/></svg></a><button ref="toggle" class="mobile-nav-toggle" @click="menu=!menu" :aria-expanded="menu" aria-controls="main-navigation" :aria-label="en?'Toggle navigation':'打开主导航'">☰</button></div></header><div v-if="isDoc" class="mobile-docbar"><button @click="emit('directory')">☷ {{en?'Documentation menu':'文档目录'}}</button><span>0.1.0-SNAPSHOT</span></div></template>

